class Transport:
    def __init__(self, client, setpoints):
        self.client = client
        self.setpoints = setpoints
    def set_slide_x(self, value):
        return self.client.set_slide_x(value)
    def set_slide_y(self, value):
        return self.client.set_slide_y(value)
    def set_slide_z(self, value):
        return self.client.set_slide_z(value)
    def read_feedback(self):
        return self.client.read_feedback()
    def stop(self):
        return self.client.stop_motion()
    def disconnect(self):
        return self.client.disconnect()
